-- M8 contract DDL v1. Cross-owner UUIDs are references, never foreign keys.
SET LOCAL timezone = 'UTC';
CREATE TABLE knowledge.content (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), kind text NOT NULL CHECK(kind IN ('ARTICLE','PAGE')), slug text NOT NULL UNIQUE, title text NOT NULL, audience text NOT NULL CHECK(audience IN ('PUBLIC_GUEST','PUBLIC_AUTH','ASN_AUTH','STAFF_ONLY')), state text NOT NULL CHECK(state IN ('DRAFT','REVIEW','PUBLISHED','ARCHIVED')), org_id uuid, principal_id uuid NOT NULL);
GRANT SELECT, INSERT, UPDATE ON knowledge.content TO helpdesk_m8;
CREATE TABLE knowledge.revisions (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), content_id uuid NOT NULL REFERENCES knowledge.content(id), revision integer NOT NULL CHECK(revision>0), sanitized_body text NOT NULL, author_id uuid NOT NULL, UNIQUE(content_id,revision));
GRANT SELECT, INSERT ON knowledge.revisions TO helpdesk_m8;
CREATE TABLE knowledge.media (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), principal_id uuid NOT NULL, storage_key text NOT NULL UNIQUE, status text NOT NULL CHECK(status IN ('PENDING','QUARANTINED','CLEAN','REJECTED','MISSING')), visibility text NOT NULL CHECK(visibility IN ('PRIVATE','PUBLIC')), mime text NOT NULL, size_bytes bigint NOT NULL CHECK(size_bytes BETWEEN 1 AND 10485760), sha256 bytea NOT NULL CHECK(octet_length(sha256)=32), alt text NOT NULL, caption text NOT NULL, license text NOT NULL, source text NOT NULL, sanitized_from_id uuid, approved_by uuid);
GRANT SELECT, INSERT, UPDATE ON knowledge.media TO helpdesk_m8;
CREATE TABLE knowledge.content_media_refs (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), content_id uuid NOT NULL REFERENCES knowledge.content(id), media_id uuid NOT NULL REFERENCES knowledge.media(id), UNIQUE(content_id,media_id));
GRANT SELECT, INSERT, UPDATE ON knowledge.content_media_refs TO helpdesk_m8;
CREATE TABLE knowledge.drafts (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), principal_id uuid NOT NULL, form_version integer NOT NULL CHECK(form_version>0), title text NOT NULL, description text NOT NULL, expires_at timestamptz NOT NULL);
GRANT SELECT, INSERT, UPDATE ON knowledge.drafts TO helpdesk_m8;
CREATE TABLE knowledge.idempotency_records (actor_scope text NOT NULL, command text NOT NULL, target text NOT NULL, key text NOT NULL CHECK(length(key) BETWEEN 16 AND 128), payload_digest bytea NOT NULL CHECK(octet_length(payload_digest)=32), response_status integer NOT NULL CHECK(response_status BETWEEN 200 AND 299), response_body jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, PRIMARY KEY(actor_scope,command,target,key));
CREATE TABLE knowledge.outbox (event_id uuid PRIMARY KEY, event_type text NOT NULL, schema_version integer NOT NULL CHECK(schema_version>0), aggregate_id uuid NOT NULL, aggregate_version bigint NOT NULL CHECK(aggregate_version>0), occurred_at timestamptz NOT NULL, correlation_id uuid NOT NULL, payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'), digest bytea NOT NULL CHECK(octet_length(digest)=32));
CREATE TABLE knowledge.outbox_delivery (event_id uuid NOT NULL REFERENCES knowledge.outbox(event_id), consumer_id text NOT NULL CHECK(consumer_id ~ '^M[1-9]$'), state text NOT NULL CHECK(state IN ('PENDING','LEASED','ACKED','DEAD_LETTER')), attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0), lease_until timestamptz, acked_at timestamptz, last_error_code text, PRIMARY KEY(event_id,consumer_id), CHECK((state='ACKED')=(acked_at IS NOT NULL)));
CREATE TABLE knowledge.inbox (consumer_id text NOT NULL, event_id uuid NOT NULL, digest bytea NOT NULL CHECK(octet_length(digest)=32), aggregate_id uuid NOT NULL, aggregate_version bigint NOT NULL CHECK(aggregate_version>0), received_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(consumer_id,event_id));
CREATE TABLE knowledge.audit_intents (id uuid PRIMARY KEY, actor_id uuid NOT NULL, action text NOT NULL, object_id uuid NOT NULL, scope text NOT NULL, reason text NOT NULL, outcome text NOT NULL, correlation_id uuid NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON knowledge.idempotency_records, knowledge.outbox, knowledge.inbox, knowledge.audit_intents TO helpdesk_m8;
GRANT SELECT, INSERT, UPDATE ON knowledge.outbox_delivery TO helpdesk_m8;
CREATE INDEX ON knowledge.outbox_delivery (state, lease_until, event_id) WHERE state<>'ACKED';
CREATE INDEX ON knowledge.content (audience,state,updated_at DESC,id DESC);
CREATE INDEX ON knowledge.media (principal_id,updated_at DESC,id DESC);
REVOKE ALL ON ALL TABLES IN SCHEMA knowledge FROM PUBLIC;
